559: /// caller owns returned memory
560: fn ccPrintFileName(args: CCPrintFileNameOptions) ![:0]u8 {
561:     const allocator = args.allocator;
562: 
563:     // Detect infinite loops.
564:     var env_map = std.process.getEnvMap(allocator) catch |err| switch (err) {
565:         error.Unexpected => unreachable, // WASI-only
566:         else => |e| return e,
567:     };
568:     defer env_map.deinit();
569:     const skip_cc_env_var = if (env_map.get(inf_loop_env_key)) |phase| blk: {
570:         if (std.mem.eql(u8, phase, "1")) {
571:             try env_map.put(inf_loop_env_key, "2");
572:             break :blk true;
573:         } else {
574:             return error.ZigIsTheCCompiler;
575:         }
576:     } else blk: {
577:         try env_map.put(inf_loop_env_key, "1");
578:         break :blk false;
579:     };
580: 
581:     var argv = std.array_list.Managed([]const u8).init(allocator);
582:     defer argv.deinit();
583: 
584:     const arg1 = try std.fmt.allocPrint(allocator, "-print-file-name={s}", .{args.search_basename});
585:     defer allocator.free(arg1);
586: 
587:     try appendCcExe(&argv, skip_cc_env_var);
588:     try argv.append(arg1);
589: 
590:     const run_res = std.process.Child.run(.{
591:         .allocator = allocator,
592:         .argv = argv.items,
593:         .max_output_bytes = 1024 * 1024,
594:         .env_map = &env_map,
595:         // Some C compilers, such as Clang, are known to rely on argv[0] to find the path
596:         // to their own executable, without even bothering to resolve PATH. This results in the message:
597:         // error: unable to execute command: Executable "" doesn't exist!
598:         // So we use the expandArg0 variant of ChildProcess to give them a helping hand.
599:         .expand_arg0 = .expand,
600:     }) catch |err| switch (err) {
601:         error.OutOfMemory => return error.OutOfMemory,
602:         else => return error.UnableToSpawnCCompiler,
603:     };
604:     defer {
605:         allocator.free(run_res.stdout);
606:         allocator.free(run_res.stderr);
607:     }
608:     switch (run_res.term) {
609:         .Exited => |code| if (code != 0) {
610:             printVerboseInvocation(argv.items, args.search_basename, args.verbose, run_res.stderr);
611:             return error.CCompilerExitCode;
612:         },
613:         else => {
614:             printVerboseInvocation(argv.items, args.search_basename, args.verbose, run_res.stderr);
615:             return error.CCompilerCrashed;
616:         },
617:     }
618: 
619:     var it = std.mem.tokenizeAny(u8, run_res.stdout, "\n\r");
620:     const line = it.next() orelse return error.LibCRuntimeNotFound;
621:     // When this command fails, it returns exit code 0 and duplicates the input file name.
622:     // So we detect failure by checking if the output matches exactly the input.
623:     if (std.mem.eql(u8, line, args.search_basename)) return error.LibCRuntimeNotFound;
624:     switch (args.want_dirname) {
625:         .full_path => return allocator.dupeZ(u8, line),
626:         .only_dir => {
627:             const dirname = fs.path.dirname(line) orelse return error.LibCRuntimeNotFound;
628:             return allocator.dupeZ(u8, dirname);
629:         },
630:     }
631: }
