633: fn printVerboseInvocation(
634:     argv: []const []const u8,
635:     search_basename: ?[]const u8,
636:     verbose: bool,
637:     stderr: ?[]const u8,
638: ) void {
639:     if (!verbose) return;
640: 
641:     if (search_basename) |s| {
642:         std.debug.print("Zig attempted to find the file '{s}' by executing this command:\n", .{s});
643:     } else {
644:         std.debug.print("Zig attempted to find the path to native system libc headers by executing this command:\n", .{});
645:     }
646:     for (argv, 0..) |arg, i| {
647:         if (i != 0) std.debug.print(" ", .{});
648:         std.debug.print("{s}", .{arg});
649:     }
650:     std.debug.print("\n", .{});
651:     if (stderr) |s| {
652:         std.debug.print("Output:\n==========\n{s}\n==========\n", .{s});
653:     }
654: }
