674: fn appendCcExe(args: *std.array_list.Managed([]const u8), skip_cc_env_var: bool) !void {
675:     const default_cc_exe = if (is_windows) "cc.exe" else "cc";
676:     try args.ensureUnusedCapacity(1);
677:     if (skip_cc_env_var) {
678:         args.appendAssumeCapacity(default_cc_exe);
679:         return;
680:     }
681:     const cc_env_var = std.zig.EnvVar.CC.getPosix() orelse {
682:         args.appendAssumeCapacity(default_cc_exe);
683:         return;
684:     };
685:     // Respect space-separated flags to the C compiler.
686:     var it = std.mem.tokenizeScalar(u8, cc_env_var, ' ');
687:     while (it.next()) |arg| {
688:         try args.append(arg);
689:     }
690: }
