692: /// These are basenames. This data is produced with a pure function. See also
693: /// `CsuPaths`.
694: pub const CrtBasenames = struct {
695:     crt0: ?[]const u8 = null,
696:     crti: ?[]const u8 = null,
697:     crtbegin: ?[]const u8 = null,
698:     crtend: ?[]const u8 = null,
699:     crtn: ?[]const u8 = null,
700: 
701:     pub const GetArgs = struct {
702:         target: *const std.Target,
703:         link_libc: bool,
704:         output_mode: std.builtin.OutputMode,
705:         link_mode: std.builtin.LinkMode,
706:         pie: bool,
707:     };
708: 
709:     /// Determine file system path names of C runtime startup objects for supported
710:     /// link modes.
711:     pub fn get(args: GetArgs) CrtBasenames {
712:         // crt objects are only required for libc.
713:         if (!args.link_libc) return .{};
714: 
715:         // Flatten crt cases.
716:         const mode: enum {
717:             dynamic_lib,
718:             dynamic_exe,
719:             dynamic_pie,
720:             static_exe,
721:             static_pie,
722:         } = switch (args.output_mode) {
723:             .Obj => return .{},
724:             .Lib => switch (args.link_mode) {
725:                 .dynamic => .dynamic_lib,
726:                 .static => return .{},
727:             },
728:             .Exe => switch (args.link_mode) {
729:                 .dynamic => if (args.pie) .dynamic_pie else .dynamic_exe,
730:                 .static => if (args.pie) .static_pie else .static_exe,
731:             },
732:         };
733: 
734:         const target = args.target;
735: 
736:         if (target.abi.isAndroid()) return switch (mode) {
737:             .dynamic_lib => .{
738:                 .crtbegin = "crtbegin_so.o",
739:                 .crtend = "crtend_so.o",
740:             },
741:             .dynamic_exe, .dynamic_pie => .{
742:                 .crtbegin = "crtbegin_dynamic.o",
743:                 .crtend = "crtend_android.o",
744:             },
745:             .static_exe, .static_pie => .{
746:                 .crtbegin = "crtbegin_static.o",
747:                 .crtend = "crtend_android.o",
748:             },
749:         };
750: 
751:         return switch (target.os.tag) {
752:             .linux => switch (mode) {
753:                 .dynamic_lib => .{
754:                     .crti = "crti.o",
755:                     .crtn = "crtn.o",
756:                 },
757:                 .dynamic_exe => .{
758:                     .crt0 = "crt1.o",
759:                     .crti = "crti.o",
760:                     .crtn = "crtn.o",
761:                 },
762:                 .dynamic_pie => .{
763:                     .crt0 = "Scrt1.o",
764:                     .crti = "crti.o",
765:                     .crtn = "crtn.o",
766:                 },
767:                 .static_exe => .{
768:                     .crt0 = "crt1.o",
769:                     .crti = "crti.o",
770:                     .crtn = "crtn.o",
771:                 },
772:                 .static_pie => .{
773:                     .crt0 = "rcrt1.o",
774:                     .crti = "crti.o",
775:                     .crtn = "crtn.o",
776:                 },
777:             },
778:             .dragonfly => switch (mode) {
779:                 .dynamic_lib => .{
780:                     .crti = "crti.o",
781:                     .crtbegin = "crtbeginS.o",
782:                     .crtend = "crtendS.o",
783:                     .crtn = "crtn.o",
784:                 },
785:                 .dynamic_exe => .{
786:                     .crt0 = "crt1.o",
787:                     .crti = "crti.o",
788:                     .crtbegin = "crtbegin.o",
789:                     .crtend = "crtend.o",
790:                     .crtn = "crtn.o",
