482: pub fn intAlignment(target: *const std.Target, bits: u16) u16 {
483:     return switch (target.cpu.arch) {
484:         .x86 => switch (bits) {
485:             0 => 0,
486:             1...8 => 1,
487:             9...16 => 2,
488:             17...32 => 4,
489:             33...64 => switch (target.os.tag) {
490:                 .uefi, .windows => 8,
491:                 else => 4,
492:             },
493:             else => 16,
494:         },
495:         .x86_64 => switch (bits) {
496:             0 => 0,
497:             1...8 => 1,
498:             9...16 => 2,
499:             17...32 => 4,
500:             33...64 => 8,
501:             else => 16,
502:         },
503:         else => return @min(
504:             std.math.ceilPowerOfTwoPromote(u16, @as(u16, @intCast((@as(u17, bits) + 7) / 8))),
505:             target.cMaxIntAlignment(),
506:         ),
507:     };
508: }
