122:     /// if available.
123:     pub inline fn getMaxRss(rus: ResourceUsageStatistics) ?usize {
124:         switch (native_os) {
125:             .linux => {
126:                 if (rus.rusage) |ru| {
127:                     return @as(usize, @intCast(ru.maxrss)) * 1024;
128:                 } else {
129:                     return null;
130:                 }
131:             },
132:             .windows => {
133:                 if (rus.rusage) |ru| {
134:                     return ru.PeakWorkingSetSize;
