151:     const rusage_init = switch (native_os) {
152:         .linux, .driverkit, .ios, .maccatalyst, .macos, .tvos, .visionos, .watchos => @as(?posix.rusage, null),
153:         .windows => @as(?windows.VM_COUNTERS, null),
154:         else => {},
155:     };
